/* select-model-guard.test.mjs — Permanent universal guard against broken
 * select-screen models (owner law 2026-10-23).
 *
 * THE LAW: No broken/untextured/wrong-model fighter may appear on the
 * character select screen, ever — not now, not for any future character.
 * If a fighter's proper model isn't ready, they get a "model coming"
 * placeholder card. NEVER a broken Tekken body or untextured model.
 *
 * WHAT THIS GUARDS: game/data/model-readiness.json (generated by
 * tools/model-validate/validate_select_models.py) records every fighter's
 * select-card model status. This test FAILS the build if any fighter is
 * 'broken' or 'missing' — the PR cannot merge until the model is fixed
 * or the fighter is explicitly marked "coming soon" (which the select
 * screen renders as a placeholder, never a broken body).
 *
 * To mark a fighter as intentionally unready: set their status to
 * "coming_soon" in the readiness file with a reason. The select screen
 * shows a MODEL COMING card. "broken"/"missing" always fail.
 *
 * Run: node --test game/tests/select-model-guard.test.mjs (from repo root)
 */
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
const READINESS = join(ROOT, 'game', 'data', 'model-readiness.json');

test('model-readiness.json exists and is valid', () => {
  assert.ok(existsSync(READINESS),
    'game/data/model-readiness.json missing — run tools/model-validate/validate_select_models.py');
  const data = JSON.parse(readFileSync(READINESS, 'utf8'));
  assert.ok(data.fighters && typeof data.fighters === 'object',
    'model-readiness.json has no fighters map');
  assert.ok(Object.keys(data.fighters).length >= 55,
    `expected 55+ fighters, got ${Object.keys(data.fighters).length}`);
});

test('no fighter has a broken select model', () => {
  const data = JSON.parse(readFileSync(READINESS, 'utf8'));
  const bad = Object.entries(data.fighters)
    .filter(([, v]) => v.status === 'broken')
    .map(([fid, v]) => `${fid} (${v.model}): ${(v.issues || []).join('; ')}`);
  assert.equal(bad.length, 0,
    `BROKEN select models — fix the model or mark coming_soon:\n  ${bad.join('\n  ')}`);
});

test('no fighter is missing its select model', () => {
  const data = JSON.parse(readFileSync(READINESS, 'utf8'));
  const missing = Object.entries(data.fighters)
    .filter(([, v]) => v.status === 'missing')
    .map(([fid, v]) => `${fid} (${v.model}): ${(v.issues || []).join('; ')}`);
  assert.equal(missing.length, 0,
    `MISSING select models — wire the model or mark coming_soon:\n  ${missing.join('\n  ')}`);
});

test('coming_soon fighters have a reason', () => {
  const data = JSON.parse(readFileSync(READINESS, 'utf8'));
  const noReason = Object.entries(data.fighters)
    .filter(([, v]) => v.status === 'coming_soon' && !(v.issues || []).length)
    .map(([fid]) => fid);
  assert.equal(noReason.length, 0,
    `coming_soon fighters must document why: ${noReason.join(', ')}`);
});

test('every fighter resolves to a MODEL_URLS key', () => {
  // Cross-check: the readiness file's model keys must all exist in assets.js
  // (catches stale readiness data after a model-key rename).
  const data = JSON.parse(readFileSync(READINESS, 'utf8'));
  const assetsSrc = readFileSync(join(ROOT, 'game', 'js', 'assets.js'), 'utf8');
  const stale = Object.entries(data.fighters)
    .filter(([, v]) => {
      if (!v.model) return false;
      // match quoted or unquoted keys: 'key':, "key":, or key:
      const pat = new RegExp(`['"]?${v.model.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}['"]?\\s*:`);
      return !pat.test(assetsSrc);
    })
    .map(([fid, v]) => `${fid}: ${v.model}`);
  assert.equal(stale.length, 0,
    `readiness file references MODEL_URLS keys not in assets.js (stale data):\n  ${stale.join('\n  ')}`);
});
